#[test]
fn retry_lane_receipt_identity_contract_preserves_history_and_command_parity() {
    let history = [
        ("tester", "attempt-tester-1", "packet-tester-1", "rework"),
        ("coder", "attempt-coder-1", "packet-coder-1", "pass"),
        ("tester", "attempt-tester-2", "packet-tester-2", "pass"),
    ];
    assert_eq!(history[0].0, "tester");
    assert_eq!(history[0].3, "rework");
    assert_eq!(history[2].0, "tester");
    assert_eq!(history[2].3, "pass");
    assert_ne!(history[0].1, history[2].1);
    assert_ne!(history[0].2, history[2].2);

    let request = serde_json::json!({
        "request_id": "request-tester-2",
        "run_id": "run-retry",
        "task_id": "task-retry",
        "dispatch_target": "tester",
        "attempt_id": history[2].1,
        "packet_id": history[2].2,
        "packet_path": "state/packets/tester-2.json",
        "backend_id": "internal_subagents"
    });
    let current_result = serde_json::json!({
        "request_id": "request-tester-2",
        "run_id": "run-retry",
        "task_id": "task-retry",
        "dispatch_target": "tester",
        "attempt_id": history[2].1,
        "packet_id": history[2].2,
        "source_dispatch_packet_path": "state/packets/tester-2.json",
        "selected_backend": "internal_subagents"
    });
    assert!(host_bridge_dispatch_identity_blockers(&request, &current_result).is_empty());

    let stale_attempt_result = serde_json::json!({
        "request_id": "request-tester-2",
        "run_id": "run-retry",
        "task_id": "task-retry",
        "dispatch_target": "tester",
        "attempt_id": history[0].1,
        "packet_id": history[2].2,
        "source_dispatch_packet_path": "state/packets/tester-2.json",
        "selected_backend": "internal_subagents"
    });
    let stale_attempt_blockers =
        host_bridge_dispatch_identity_blockers(&request, &stale_attempt_result);
    assert!(stale_attempt_blockers
        .iter()
        .any(|code| code.ends_with(":attempt_id")));

    let different_packet_result = serde_json::json!({
        "request_id": "request-tester-2",
        "run_id": "run-retry",
        "task_id": "task-retry",
        "dispatch_target": "tester",
        "attempt_id": history[2].1,
        "packet_id": history[0].2,
        "source_dispatch_packet_path": "state/packets/tester-1.json",
        "selected_backend": "internal_subagents"
    });
    let different_packet_blockers =
        host_bridge_dispatch_identity_blockers(&request, &different_packet_result);
    assert!(different_packet_blockers
        .iter()
        .any(|code| code.ends_with(":packet_id")));
    assert!(different_packet_blockers
        .iter()
        .any(|code| code.ends_with(":packet_path")));

    let suggested_command =
        "vida agent host-bridge --request <request> --submit-result <result> --receipt-id <id>";
    assert!(suggested_command.starts_with("vida agent host-bridge"));
    assert!(!suggested_command.contains("--json"));
}

#[cfg(windows)]
#[test]
fn vida_dispatch_validator_matches_completion_validator_for_packet_path_spellings() {
    let root = std::env::temp_dir().join(format!(
        "vida-task-smoke-path-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock")
            .as_nanos()
    ));
    let packet_dir = root.join("runtime-consumption/dispatch-packets");
    fs::create_dir_all(&packet_dir).expect("create packet directory");
    let packet = packet_dir.join("current.json");
    let other = packet_dir.join("other.json");
    fs::write(&packet, "{}").expect("write packet");
    fs::write(&other, "{}").expect("write other packet");
    let normal = packet.display().to_string();
    let extended = format!(r"\\?\{}", normal);
    let mixed = normal.replace('\\', "/");
    let request = serde_json::json!({
        "request_id": "req-path",
        "run_id": "run-path",
        "task_id": "task-path",
        "dispatch_target": "tester",
        "attempt_id": "attempt-path",
        "packet_id": "packet-path",
        "packet_path": normal,
        "backend_id": "internal_subagents",
    });
    let result = serde_json::json!({
        "request_id": "req-path",
        "run_id": "run-path",
        "task_id": "task-path",
        "dispatch_target": "tester",
        "attempt_id": "attempt-path",
        "packet_id": "packet-path",
        "source_dispatch_packet_path": mixed,
        "selected_backend": "internal_subagents",
        "completion_receipt_id": "completion-path",
    });
    let receipt = serde_json::json!({
        "request_id": "req-path",
        "run_id": "run-path",
        "dispatch_target": "tester",
        "source_dispatch_packet_path": extended,
        "completion_receipt_id": "completion-path",
        "receipt_backed": true,
    });

    assert!(host_bridge_dispatch_identity_blockers(&request, &result).is_empty());
    assert!(host_bridge_completion_identity_matches(
        &request, &result, Some(&receipt), "run-path", "tester", &normal
    ));
    let mut foreign = result.clone();
    foreign["source_dispatch_packet_path"] = serde_json::json!(other.display().to_string());
    assert!(
        host_bridge_dispatch_identity_blockers(&request, &foreign)
            .iter()
            .any(|code| code.ends_with(":packet_path"))
    );
    assert!(!host_bridge_completion_identity_matches(
        &request,
        &foreign,
        Some(&receipt),
        "run-path",
        "tester",
        &normal
    ));

    let _ = fs::remove_dir_all(root);
}

#[test]
fn legacy_host_bridge_request_uses_current_packet_scoped_receipt_only() {
    let state_dir = unique_state_dir();
    let run_id = unique_test_id("legacy-host-bridge-retry");
    let parent_id = unique_test_id("legacy-host-bridge-parent");
    let request_id = format!("{}-request", run_id);
    let packet_rel = "runtime-consumption/dispatch-packets/current.json";
    let stale_packet_rel = "runtime-consumption/dispatch-packets/stale.json";
    let packet_path = format!("{}/{}", state_dir, packet_rel);
    let stale_packet_path = format!("{}/{}", state_dir, stale_packet_rel);
    let bridge_dir = format!("{}/host-tool-bridge", state_dir);
    let request_path = format!("{}/requests/request.json", bridge_dir);
    let result_path = format!("{}/results/result.json", bridge_dir);
    let receipt_path = format!("{}/receipts/receipt.json", bridge_dir);
    let artifact_path = format!("{}/attempt-artifacts/patch-proposal.json", state_dir);

    run_and_assert_success(&["boot"], &state_dir);
    create_epic_parent(&state_dir, &parent_id, "Legacy host bridge parent", "open");
    create_task_fixture_row(
        &state_dir,
        &run_id,
        "Legacy host bridge retry",
        "task",
        "in_progress",
        Some(&parent_id),
    );
    run_and_assert_success(
        &["taskflow", "run-graph", "init", &run_id, "coder"],
        &state_dir,
    );
    fs::create_dir_all(format!(
        "{}/runtime-consumption/dispatch-packets",
        state_dir
    ))
    .expect("create packet dir");
    fs::create_dir_all(format!("{}/requests", bridge_dir)).expect("create request dir");
    fs::create_dir_all(format!("{}/results", bridge_dir)).expect("create result dir");
    fs::create_dir_all(format!("{}/receipts", bridge_dir)).expect("create receipt dir");
    fs::create_dir_all(format!("{}/attempt-artifacts", state_dir))
        .expect("create attempt artifact dir");

    let packet = serde_json::json!({
        "run_id": run_id,
        "task_id": run_id,
        "dispatch_target": "coder",
        "selected_backend": "internal_subagents",
        "delivery_task_packet": {
            "packet_id": format!("{}::coder::delivery", run_id),
            "task_id": run_id
        }
    });
    fs::write(&packet_path, packet.to_string()).expect("write legacy packet");
    let stale_packet = serde_json::json!({
        "run_id": run_id,
        "task_id": run_id,
        "dispatch_target": "coder",
        "selected_backend": "internal_subagents",
        "delivery_task_packet": {
            "packet_id": format!("{}::coder::delivery", run_id),
            "task_id": run_id
        }
    });
    fs::write(&stale_packet_path, stale_packet.to_string()).expect("write stale packet");
    fs::write(
        &artifact_path,
        serde_json::json!({
            "artifact_kind": "patch_proposal",
            "changed_files": ["crates/vida/src/agent_dispatch_surface.rs"]
        })
        .to_string(),
    )
    .expect("write patch proposal");

    let canonical_packet_path = fs::canonicalize(&packet_path)
        .expect("canonical current packet")
        .display()
        .to_string();
    let canonical_stale_packet_path = fs::canonicalize(&stale_packet_path)
        .expect("canonical stale packet")
        .display()
        .to_string();
    let persisted_path_identity = |path: &str| {
        #[cfg(windows)]
        {
            path.strip_prefix(r"\\?\")
                .or_else(|| path.strip_prefix("//?/"))
                .unwrap_or(path)
                .to_string()
        }
        #[cfg(not(windows))]
        {
            path.to_string()
        }
    };
    let persisted_packet_path = persisted_path_identity(&canonical_packet_path);
    let persisted_stale_packet_path = persisted_path_identity(&canonical_stale_packet_path);
    let request = serde_json::json!({
        "schema_version": 1,
        "status": "pending",
        "request_id": request_id,
        "run_id": run_id,
        "task_id": run_id,
        "legacy_artifact": true,
        "dispatch_target": "coder",
        "runtime_role": "worker",
        "task_class": "implementation",
        "packet_path": canonical_packet_path,
        "backend_id": "internal_subagents",
        "carrier_id": "junior",
        "execution_boundary": "parent_host_session",
        "dispatch_transport": "host_tool_bridge",
        "receipt_mode": "host_bridge_receipt",
        "adapter_kind": "codex_host_tools",
        "adapter_capability_id": "codex.multi_agent_v1",
        "invocation_mode": "parent_host_tool_api",
        "expected_implementation_artifact_kinds": [
            "patch_proposal",
            "isolated_worktree_manifest"
        ],
        "owned_paths": ["crates/vida/src/agent_dispatch_surface.rs"],
        "proof_artifact_paths": [],
        "implementation_isolation": {
            "owned_paths": ["crates/vida/src/agent_dispatch_surface.rs"]
        },
        "request_path": request_path,
        "result_path": result_path,
        "receipt_path": receipt_path
    });
    fs::write(&request_path, request.to_string()).expect("write legacy request");

    let runtime = Runtime::new().expect("create tokio runtime");
    runtime.block_on(async {
        let db: Surreal<Db> = Surreal::new::<SurrealKv>(&state_dir)
            .await
            .expect("open surreal store");
        db.use_ns("vida")
            .use_db("primary")
            .await
            .expect("select surreal database");
        let current_receipt = serde_json::json!({
            "run_id": run_id,
            "dispatch_target": "coder",
            "dispatch_status": "blocked",
            "lane_status": "lane_blocked",
            "dispatch_kind": "agent_lane",
            "dispatch_surface": "vida agent-init",
            "dispatch_command": "vida agent-init --dispatch-packet packet --execute-dispatch",
            "dispatch_packet_path": persisted_packet_path,
            "dispatch_result_path": "host-tool-bridge/results/result.json",
            "blocker_code": "host_tool_bridge_adapter_required",
            "downstream_dispatch_target": "tester",
            "downstream_dispatch_ready": false,
            "downstream_dispatch_blockers": ["host_tool_bridge_adapter_required"],
            "downstream_dispatch_status": "blocked",
            "downstream_dispatch_executed_count": 0,
            "downstream_dispatch_active_target": "coder",
            "activation_agent_type": "junior",
            "activation_runtime_role": "worker",
            "selected_backend": "internal_subagents",
            "recorded_at": "2026-07-17T13:58:17Z"
        });
        let stale_receipt = serde_json::json!({
            "run_id": run_id,
            "dispatch_target": "coder",
            "dispatch_status": "blocked",
            "lane_status": "lane_blocked",
            "dispatch_kind": "agent_lane",
            "dispatch_surface": "vida agent-init",
            "dispatch_command": "vida agent-init --dispatch-packet packet --execute-dispatch",
            "dispatch_packet_path": persisted_stale_packet_path,
            "dispatch_result_path": "host-tool-bridge/results/stale-result.json",
            "blocker_code": "host_tool_bridge_adapter_required",
            "downstream_dispatch_target": "tester",
            "downstream_dispatch_ready": false,
            "downstream_dispatch_blockers": ["host_tool_bridge_adapter_required"],
            "downstream_dispatch_status": "blocked",
            "downstream_dispatch_executed_count": 0,
            "downstream_dispatch_active_target": "coder",
            "activation_agent_type": "junior",
            "activation_runtime_role": "worker",
            "selected_backend": "internal_subagents",
            "recorded_at": "2026-07-17T12:06:37Z"
        });
        db.query(
            "UPSERT type::record('run_graph_dispatch_receipt', $run) CONTENT $current; \
             UPSERT type::record('run_graph_dispatch_lane_receipt', $current_id) CONTENT $current; \
             UPSERT type::record('run_graph_dispatch_lane_receipt', $stale_id) CONTENT $stale;",
        )
        .bind(("run", run_id.clone()))
        .bind(("current_id", format!("{}-current", run_id)))
        .bind(("stale_id", format!("{}-stale", run_id)))
        .bind(("current", current_receipt))
        .bind(("stale", stale_receipt))
        .await
        .expect("seed current projection and packet receipt history");
        drop(db);
    });

    let (current, current_success) = run_command_json_allow_failure(
        &[
            "agent",
            "host-bridge",
            "--request",
            &request_path,
            "--attach-artifact",
            &artifact_path,
            "--artifact-kind",
            "patch_proposal",
            "--changed-file",
            "crates/vida/src/agent_dispatch_surface.rs",
            "--attempt-id",
            "legacy-current-attempt",
            "--consolidation-receipt",
            "legacy-current-receipt",
            "--state-dir",
            &state_dir,
            "--json",
        ],
        &state_dir,
    );
    assert!(
        current_success,
        "legacy current receipt should be accepted: {current}"
    );
    assert_eq!(current["status"], "pass", "current request: {current}");
    assert!(
        !current["blocker_codes"]
            .as_array()
            .expect("current blocker codes")
            .iter()
            .any(|code| code == "authoritative_state_store_locked"),
        "full attach must reuse its validated provenance snapshot after writable request persistence: {current}"
    );
    assert!(
        !current["blocker_codes"]
            .as_array()
            .expect("current blocker codes")
            .iter()
            .any(|code| code == "host_bridge_dispatch_receipt_mismatch")
    );
    let updated_request: Value = serde_json::from_str(
        &fs::read_to_string(&request_path).expect("read attached legacy request"),
    )
    .expect("attached legacy request should remain JSON");
    assert_eq!(updated_request["attempt_id"], Value::Null);
    assert_eq!(updated_request["packet_id"], Value::Null);
    assert_eq!(updated_request["packet_path"], canonical_packet_path);

    let mut stale_request = request.clone();
    stale_request["request_id"] = serde_json::json!(format!("{}-stale-request", run_id));
    stale_request["packet_path"] = serde_json::json!(canonical_stale_packet_path);
    fs::write(&request_path, stale_request.to_string()).expect("write stale request");

    let (stale, stale_success) = run_command_json_allow_failure(
        &[
            "agent",
            "host-bridge",
            "--request",
            &request_path,
            "--attach-artifact",
            &artifact_path,
            "--artifact-kind",
            "patch_proposal",
            "--changed-file",
            "crates/vida/src/agent_dispatch_surface.rs",
            "--attempt-id",
            "legacy-stale-attempt",
            "--consolidation-receipt",
            "legacy-stale-receipt",
            "--state-dir",
            &state_dir,
            "--json",
        ],
        &state_dir,
    );
    assert!(
        !stale_success,
        "stale same-role packet must fail closed: {stale}"
    );
    assert_eq!(stale["status"], "blocked");
    assert!(
        stale["blocker_codes"]
            .as_array()
            .expect("stale blocker codes")
            .iter()
            .any(|code| code == "host_bridge_dispatch_receipt_mismatch")
    );

    let _ = fs::remove_dir_all(state_dir);
}

fn unique_state_dir() -> String {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    static UNIQUE_DIR_COUNTER: AtomicU64 = AtomicU64::new(0);
    let counter = UNIQUE_DIR_COUNTER.fetch_add(1, Ordering::Relaxed);
    format!(
        "/tmp/vida-task-state-{}-{}-{}",
        std::process::id(),
        nanos,
        counter
    )
}

fn unique_test_id(prefix: &str) -> String {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    static UNIQUE_ID_COUNTER: AtomicU64 = AtomicU64::new(0);
    let counter = UNIQUE_ID_COUNTER.fetch_add(1, Ordering::Relaxed);
    format!("{}-{}-{}-{}", prefix, std::process::id(), nanos, counter)
}

fn run_and_assert_failure(args: &[&str], state_dir: &str) -> (String, String) {
    let output = vida()
        .args(args)
        .env("VIDA_STATE_DIR", state_dir)
        .output()
        .expect("run vida command");
    assert!(
        !output.status.success(),
        "expected vida command to fail: {:?}",
        args
    );
    (
        String::from_utf8_lossy(&output.stdout).to_string(),
        String::from_utf8_lossy(&output.stderr).to_string(),
    )
}

