fn run_command_capture(args: &[&str], state_dir: &str) -> std::process::Output {
    run_with_state_lock_retry(|| {
        let mut command = vida();
        command.args(args).env("VIDA_STATE_DIR", state_dir);
        command
    })
}

fn run_command_json(args: &[&str], state_dir: &str) -> serde_json::Value {
    let output = run_with_state_lock_retry(|| {
        let mut command = vida();
        command.args(args).env("VIDA_STATE_DIR", state_dir);
        command
    });
    assert!(
        output.status.success(),
        "args: {args:?}\nstatus: {:?}\nstdout: {}\nstderr: {}",
        output.status.code(),
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).expect("json output should parse")
}

fn assert_task_release1_contract(
    surface: &str,
    args: &[&str],
    state_dir: &str,
) -> serde_json::Value {
    let json = run_command_json(args, state_dir);
    vida_test_support::assert_release1_operator_shape(surface, &json);
    json
}

fn run_command_json_with_session(
    args: &[&str],
    state_dir: &str,
    session_id: &str,
) -> serde_json::Value {
    let output = run_with_state_lock_retry(|| {
        let mut command = vida();
        command
            .args(args)
            .env("VIDA_STATE_DIR", state_dir)
            .env("VIDA_SESSION_ID", session_id);
        command
    });
    assert!(
        output.status.success(),
        "args: {args:?}\nstatus: {:?}\nstdout: {}\nstderr: {}",
        output.status.code(),
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).expect("json output should parse")
}

fn run_command_json_allow_failure(args: &[&str], state_dir: &str) -> (serde_json::Value, bool) {
    let output = run_command_capture(args, state_dir);
    let json = serde_json::from_slice(&output.stdout).unwrap_or_else(|error| {
        panic!(
            "json output should parse for args {args:?}: {error}\nstatus: {:?}\nstdout: {}\nstderr: {}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        )
    });
    (json, output.status.success())
}

#[test]
fn requirement_analysis_cli_contract() {
    let state_dir = unique_state_dir();
    fs::create_dir_all(&state_dir).expect("create state dir");

    let help = run_command_capture(&["requirement", "analyze", "--help"], &state_dir);
    assert!(help.status.success());
    let help_text = format!(
        "{}{}",
        String::from_utf8_lossy(&help.stdout),
        String::from_utf8_lossy(&help.stderr)
    );
    for expected in [
        "--input <TEXT>",
        "--source-file <SOURCE_FILE>",
        "--task-id <TASK_ID>",
        "--request-id <REQUEST_ID>",
        "--depth-mode <DEPTH_MODE>",
        "--artifact-path <ARTIFACT_PATH>",
        "--json",
        "readiness_verdict",
        "output_contract",
        "developer_handoff",
    ] {
        assert!(
            help_text.contains(expected),
            "requirement analyze help must document {expected}: {help_text}"
        );
    }

    let json = run_command_json(
        &[
            "requirement",
            "analyze",
            "--task-id",
            "task-1",
            "--request-id",
            "request-1",
            "--input",
            "Use meeting-specific event form fields. Add widget tests.",
            "--depth-mode",
            "critical",
            "--artifact-path",
            "artifacts/requirement-analysis/task-1.json",
            "--codebase-inspected",
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(json["surface"], "vida requirement analyze");
    assert_eq!(json["status"], "pass");
    vida_test_support::assert_release1_operator_shape("vida requirement analyze", &json);
    let artifact = &json["artifact"];
    assert_eq!(
        artifact["schema_version"],
        "requirement-analysis-artifact.v1"
    );
    assert_eq!(artifact["task_id"], "task-1");
    assert_eq!(artifact["request_id"], "request-1");
    assert_eq!(artifact["depth_mode"], "critical");
    assert_eq!(artifact["readiness_verdict"], "ready_for_developer_handoff");
    assert_eq!(
        artifact["artifact_path"],
        "artifacts/requirement-analysis/task-1.json"
    );
    for field in [
        "source_inputs",
        "requirement_classification",
        "requirement_atoms",
        "selected_methods",
        "selected_roles",
        "role_findings_summary",
        "detected_conflicts",
        "open_questions",
        "working_assumptions",
        "solution_options",
        "recommended_option",
        "downstream_routes",
        "acceptance_criteria",
        "test_matrix",
        "output_contract",
        "codebase_impact",
        "developer_handoff",
    ] {
        assert!(
            !artifact[field].is_null(),
            "artifact must expose required field {field}: {artifact}"
        );
    }
    assert!(artifact["open_questions"]["critical"].is_array());
    assert!(artifact["open_questions"]["important"].is_array());
    assert!(artifact["open_questions"]["optional"].is_array());
    assert_eq!(artifact["codebase_impact"]["inspected"], true);
    assert_eq!(
        artifact["output_contract"]["default"]["mode"],
        "compact_toon_plain"
    );
    assert_eq!(
        artifact["output_contract"]["json"]["mode"],
        "machine_readable"
    );
    assert_eq!(artifact["challenge_route"]["recommended"], true);
    assert!(
        artifact["challenge_route"]["trigger_matches"]
            .as_array()
            .expect("challenge route trigger matches should render")
            .iter()
            .any(|trigger| trigger["trigger_id"] == "critical_depth")
    );
    assert!(
        artifact["developer_handoff"]["proof_targets"]
            .as_array()
            .expect("developer_handoff proof targets should render")
            .iter()
            .any(|target| target
                .as_str()
                .is_some_and(|text| text.contains("requirement_analysis_cli_contract")))
    );

    let (missing_identity, missing_identity_success) =
        run_command_json_allow_failure(&["requirement", "analyze", "--json"], &state_dir);
    assert!(!missing_identity_success);
    vida_test_support::assert_release1_operator_shape(
        "vida requirement analyze",
        &missing_identity,
    );
    assert_eq!(missing_identity["status"], "blocked");
    assert_eq!(
        missing_identity["blocker_codes"],
        serde_json::json!(["missing_requirement_identity"])
    );

    let (unreadable_source, unreadable_source_success) = run_command_json_allow_failure(
        &[
            "requirement",
            "analyze",
            "--task-id",
            "task-1",
            "--source-file",
            "missing-requirement-source.md",
            "--json",
        ],
        &state_dir,
    );
    assert!(!unreadable_source_success);
    vida_test_support::assert_release1_operator_shape(
        "vida requirement analyze",
        &unreadable_source,
    );
    assert_eq!(unreadable_source["status"], "blocked");
    assert_eq!(
        unreadable_source["blocker_codes"],
        serde_json::json!(["requirement_source_unreadable"])
    );

    let plain = run_command_capture(
        &[
            "requirement",
            "analyze",
            "--request-id",
            "request-plain-1",
            "--input",
            "Use meeting-specific event form fields.",
            "--artifact-path",
            "artifacts/requirement-analysis/task-1.json",
        ],
        &state_dir,
    );
    assert!(plain.status.success());
    let plain_text = String::from_utf8_lossy(&plain.stdout);
    assert!(plain_text.starts_with("vida requirement analyze\n"));
    assert!(plain_text.contains("readiness_verdict: ready_for_developer_handoff"));
    assert!(plain_text.contains("artifact_path: artifacts/requirement-analysis/task-1.json"));
    assert!(plain_text.contains("downstream_routes: developer_handoff"));
    assert!(plain_text.contains("developer_handoff: Implement against the requirement atoms"));

    let _ = fs::remove_dir_all(&state_dir);
}

#[test]
fn requirement_analysis_party_chat_route() {
    let (project_root, state_dir) = project_bound_state_dir();

    let (routine, routine_success) = run_command_json_allow_failure_in_cwd(
        &[
            "requirement",
            "analyze",
            "--task-id",
            "routine-requirement",
            "--input",
            "Add editable meeting event fields.",
            "--json",
        ],
        &state_dir,
        &project_root,
    );
    assert!(
        routine_success,
        "routine requirement should pass: {routine}"
    );
    assert_eq!(routine["status"], "pass");
    assert_eq!(routine["artifact"]["challenge_route"]["recommended"], false);
    assert_eq!(
        routine["artifact"]["challenge_route"]["route_id"],
        "party_chat_challenge_round"
    );
    assert_eq!(
        routine["artifact"]["challenge_route"]["next_action"],
        "Do not run Party Chat for this routine requirement."
    );

    let (routine_cross_boundary, routine_cross_boundary_success) =
        run_command_json_allow_failure_in_cwd(
            &[
                "requirement",
                "analyze",
                "--task-id",
                "routine-cross-boundary-requirement",
                "--input",
                "Coordinate cross-boundary release notes for a clear routine update.",
                "--json",
            ],
            &state_dir,
            &project_root,
        );
    assert!(
        routine_cross_boundary_success,
        "routine cross-boundary requirement should pass: {routine_cross_boundary}"
    );
    assert_eq!(
        routine_cross_boundary["artifact"]["challenge_route"]["recommended"],
        false
    );

    let (critical, critical_success) = run_command_json_allow_failure_in_cwd(
        &[
            "requirement",
            "analyze",
            "--task-id",
            "critical-requirement",
            "--input",
            "Resolve cross-boundary API ambiguity with a multi-perspective challenge round.",
            "--depth-mode",
            "critical",
            "--json",
        ],
        &state_dir,
        &project_root,
    );
    assert!(
        critical_success,
        "critical requirement should pass: {critical}"
    );
    assert_eq!(critical["status"], "pass");
    let challenge_route = &critical["artifact"]["challenge_route"];
    assert_eq!(challenge_route["recommended"], true);
    assert_eq!(challenge_route["route_owner"], "problem-party projection");
    assert_eq!(
        challenge_route["board_flow_id"],
        "party_chat_council_modern_full"
    );
    assert!(
        challenge_route["guardrails"]
            .as_array()
            .expect("guardrails should render")
            .iter()
            .any(|guardrail| guardrail == "do_not_bypass_taskflow_writer")
    );
    let trigger_ids = challenge_route["trigger_matches"]
        .as_array()
        .expect("trigger matches should render")
        .iter()
        .filter_map(|trigger| trigger["trigger_id"].as_str())
        .collect::<Vec<_>>();
    assert!(trigger_ids.contains(&"critical_depth"));
    assert!(trigger_ids.contains(&"explicit_multi_perspective_request"));
    assert!(trigger_ids.contains(&"cross_boundary_ambiguity"));

    let _ = fs::remove_dir_all(&project_root);
}

fn assert_public_surface_matrix_json_case(
    label: &str,
    args: &[&str],
    state_dir: &str,
    expected_surface: Option<&str>,
) -> serde_json::Value {
    let (json, _success) = run_command_json_allow_failure(args, state_dir);
    let status = json["status"]
        .as_str()
        .or_else(|| json["init"]["status"].as_str())
        .unwrap_or_else(|| panic!("{label} must expose status: {json}"));
    assert!(
        matches!(
            status,
            "pass" | "blocked" | "pending" | "ready" | "not_requested"
        ),
        "{label} returned non-canonical status `{status}`: {json}"
    );
    if status == "blocked" {
        assert!(
            json["blocker_codes"].as_array().is_some(),
            "{label} blocked output must expose blocker_codes: {json}"
        );
    }
    if let Some(surface) = expected_surface {
        assert_eq!(json["surface"].as_str(), Some(surface), "{label}: {json}");
    }
    json
}

fn run_command_json_allow_failure_in_cwd(
    args: &[&str],
    state_dir: &str,
    cwd: &str,
) -> (serde_json::Value, bool) {
    let output = run_with_state_lock_retry(|| {
        let mut command = vida();
        command
            .args(args)
            .env("VIDA_STATE_DIR", state_dir)
            .current_dir(cwd);
        command
    });
    let json = serde_json::from_slice(&output.stdout).unwrap_or_else(|error| {
        panic!(
            "json output should parse for args {args:?}: {error}\nstatus: {:?}\nstdout: {}\nstderr: {}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        )
    });
    (json, output.status.success())
}

fn create_epic_parent(state_dir: &str, parent_id: &str, title: &str, status: &str) {
    let parent = run_command_json(
        &[
            "task",
            "create",
            parent_id,
            title,
            "--type",
            "epic",
            "--status",
            status,
            "--priority",
            "1",
            "--json",
        ],
        state_dir,
    );
    assert_eq!(parent["status"], "pass");
}

fn create_task_fixture_row(
    state_dir: &str,
    task_id: &str,
    title: &str,
    issue_type: &str,
    status: &str,
    parent_id: Option<&str>,
) {
    let mut args = vec![
        "task",
        "create",
        task_id,
        title,
        "--type",
        issue_type,
        "--status",
        status,
        "--priority",
        "1",
    ];
    if let Some(parent_id) = parent_id {
        args.push("--parent-id");
        args.push(parent_id);
    }
    args.push("--json");
    let task = run_command_json(&args, state_dir);
    assert_eq!(task["status"], "pass");
}

fn init_git_repo(path: &str) {
    fs::create_dir_all(path).expect("create git repo dir");
    let output = Command::new("git")
        .args(["init", "--quiet"])
        .current_dir(path)
        .output()
        .expect("git init should run");
    assert!(
        output.status.success(),
        "git init failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
}

