fn assert_zombie_d_operator_shape(value: &serde_json::Value, label: &str) {
    vida_test_support::assert_release1_operator_shape(label, value);
    assert!(matches!(
        value["status"].as_str(),
        Some("pass") | Some("blocked")
    ));
    if value["status"] == "blocked" {
        assert!(
            value["blocker_codes"]
                .as_array()
                .is_some_and(|codes| !codes.is_empty()),
            "{label} blocked verdict must expose blocker_codes: {value}"
        );
        assert!(
            value["next_actions"]
                .as_array()
                .is_some_and(|actions| !actions.is_empty()),
            "{label} blocked verdict must expose next_actions: {value}"
        );
    }
}

fn assert_zombie_d_host_bridge_shape(value: &serde_json::Value) {
    assert_eq!(value["surface"], "vida agent host-bridge");
    assert!(matches!(
        value["status"].as_str(),
        Some("pass") | Some("blocked")
    ));
    assert!(value["blocker_codes"].is_array());
    assert!(value["next_actions"].is_array());
    assert!(value["artifact_refs"].is_object());
    assert_eq!(value["shared_fields"]["status"], value["status"]);
    assert_eq!(
        value["shared_fields"]["blocker_codes"],
        value["blocker_codes"]
    );
    assert_eq!(
        value["shared_fields"]["next_actions"],
        value["next_actions"]
    );
    assert_eq!(
        value["shared_fields"]["artifact_refs"],
        value["artifact_refs"]
    );
    assert_eq!(value["operator_contracts"]["status"], value["status"]);
    assert_eq!(
        value["operator_contracts"]["blocker_codes"],
        value["blocker_codes"]
    );
    assert_eq!(
        value["operator_contracts"]["next_actions"],
        value["next_actions"]
    );
    assert_eq!(
        value["operator_contracts"]["artifact_refs"],
        value["artifact_refs"]
    );
    assert!(
        value["host_bridge"]["required_result_fields"]
            .as_array()
            .is_some_and(|fields| fields.iter().any(|field| field == "allowed_next_node"))
    );
    if value["status"] == "blocked" {
        assert!(
            value["blocker_codes"]
                .as_array()
                .is_some_and(|codes| !codes.is_empty())
        );
        assert!(
            value["next_actions"]
                .as_array()
                .is_some_and(|actions| !actions.is_empty())
        );
    }
}

#[test]
fn team_flow_transition_persisted_run_graph_zombie_d() {
    let (project_root, state_dir) = project_bound_state_dir();
    let boot = run_command_capture(&["boot"], &state_dir);
    assert!(boot.status.success());

    let run_id = "team-flow-transition-persisted-run-graph-zombie-d";
    create_run_graph_backing_task(&state_dir, run_id);
    let (routing, routing_success) =
        run_command_json_allow_failure(&["taskflow", "validate-routing", "--json"], &state_dir);
    assert!(routing_success || routing["status"] == "blocked");
    assert_zombie_d_operator_shape(&routing, "vida taskflow validate-routing");
    if routing["status"] == "pass" {
        assert!(routing["route_count"].as_u64().unwrap_or_default() > 0);
    } else {
        assert!(
            routing["blocker_codes"]
                .as_array()
                .is_some_and(|codes| !codes.is_empty())
        );
    }

    let (route, route_success) = run_command_json_allow_failure(
        &[
            "taskflow",
            "route",
            "explain",
            "--dispatch-target",
            "analyst",
            "--json",
        ],
        &state_dir,
    );
    let (route_by_role, route_by_role_success) = run_command_json_allow_failure(
        &[
            "taskflow",
            "route",
            "explain",
            "--runtime-role",
            "business_analyst",
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(route["status"], route_by_role["status"]);
    assert_eq!(route_success, route_by_role_success);
    assert_eq!(route["blocker_codes"], route_by_role["blocker_codes"]);
    assert_eq!(route["next_actions"], route_by_role["next_actions"]);
    assert_eq!(route["artifact_refs"], route_by_role["artifact_refs"]);
    if route["status"] == "pass" {
        assert_eq!(
            route["route"]["selected_backend"],
            route_by_role["route"]["selected_backend"]
        );
        assert_eq!(route["route"]["dispatch_target"], "analyst");
        assert_eq!(
            route["route"]["allowed_next_node"],
            route_by_role["route"]["allowed_next_node"]
        );
    } else {
        assert!(
            route["blocker_codes"]
                .as_array()
                .is_some_and(|codes| !codes.is_empty())
        );
    }
    assert_zombie_d_operator_shape(&route, "vida taskflow route explain");
    assert_zombie_d_operator_shape(&route_by_role, "vida taskflow route explain");

    let compact = run_command_capture(
        &[
            "taskflow",
            "route",
            "explain",
            "--dispatch-target",
            "analyst",
        ],
        &state_dir,
    );
    let compact_text = format!(
        "{}{}",
        String::from_utf8_lossy(&compact.stdout),
        String::from_utf8_lossy(&compact.stderr)
    );
    assert!(!compact_text.is_empty());
    assert!(compact_text.contains("route") || compact_text.contains("blocked"));
    assert!(!compact_text.contains("--json"));
    let help = run_command_capture(&["taskflow", "route", "explain", "--help"], &state_dir);
    let help_text = format!(
        "{}{}",
        String::from_utf8_lossy(&help.stdout),
        String::from_utf8_lossy(&help.stderr)
    );
    assert!(help_text.contains("--json"));
    assert!(help_text.contains("--dispatch-target"));
    assert!(help_text.contains("--runtime-role"));

    let (dispatch, dispatch_success) = run_command_json_allow_failure(
        &[
            "agent",
            "dispatch-next",
            "--dev-team",
            "--lanes",
            "3",
            "--full",
            "--json",
        ],
        &state_dir,
    );
    assert!(
        dispatch_success || dispatch["status"] == "blocked",
        "dispatch preview must return a canonical pass or blocked verdict: {dispatch}"
    );
    if dispatch["status"] == "pass" {
        let selected = dispatch["selected_lanes"]
            .as_array()
            .expect("selected lanes should be an array");
        assert!(!selected.is_empty());
        assert!(
            matches!(
                selected[0]["role_label"].as_str(),
                Some("analyst") | Some("implementer")
            ),
            "unexpected canonical first lane: {dispatch}"
        );
    } else {
        let blockers = dispatch["blocker_codes"]
            .as_array()
            .expect("blocked dispatch should expose blocker codes");
        assert!(
            blockers.iter().any(|code| {
                matches!(
                    code.as_str(),
                    Some("dispatch_packet_contract_invalid") | Some("no_ready_task_candidates")
                )
            }),
            "dispatch mismatch must fail closed with a canonical blocker: {dispatch}"
        );
    }

    let seed = run_command_json(
        &[
            "taskflow",
            "run-graph",
            "seed",
            run_id,
            "continue development",
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(seed["payload"]["status"]["run_id"], run_id);
    let advance = run_command_json(
        &["taskflow", "run-graph", "advance", run_id, "--json"],
        &state_dir,
    );
    let next_node = advance["payload"]["status"]["next_node"]
        .as_str()
        .expect("advance should expose next_node");
    assert!(!next_node.is_empty());
    assert!(!next_node.contains('-'));

    let persisted = run_command_json(
        &["taskflow", "run-graph", "status", run_id, "--json"],
        &state_dir,
    );
    let persisted_again = run_command_json(
        &["taskflow", "run-graph", "status", run_id, "--json"],
        &state_dir,
    );
    assert_zombie_d_operator_shape(&persisted, "vida taskflow run-graph status");
    assert_zombie_d_operator_shape(&persisted_again, "vida taskflow run-graph status");
    assert_eq!(
        persisted["run_graph_status"],
        persisted_again["run_graph_status"]
    );
    assert_eq!(persisted["run_graph_status"]["next_node"], next_node);

    let status = run_command_json(&["status", "--json"], &state_dir);
    assert_zombie_d_operator_shape(&status, "vida status");
    assert_eq!(status["latest_run_graph_status"]["run_id"], run_id);

    let bridge_state_dir = unique_state_dir();
    fs::create_dir_all(&bridge_state_dir).expect("create host bridge parity state dir");
    let bridge_boot = run_and_assert_success(&["boot"], &bridge_state_dir);
    assert!(!bridge_boot.is_empty());
    let bridge_run_id = "team-flow-transition-persisted-run-graph-zombie-d-bridge";
    create_run_graph_backing_task(&bridge_state_dir, bridge_run_id);
    let dispatch_init = run_command_json(
        &[
            "taskflow",
            "run-graph",
            "dispatch-init",
            bridge_run_id,
            "--json",
        ],
        &bridge_state_dir,
    );
    let dispatch_packet_path = dispatch_init["dispatch_packet_path"]
        .as_str()
        .expect("host bridge parity dispatch should expose packet path");
    let (agent_init, agent_init_success) = run_command_json_allow_failure(
        &[
            "agent-init",
            "--dispatch-packet",
            dispatch_packet_path,
            "--execute-dispatch",
            "--json",
        ],
        &bridge_state_dir,
    );
    assert!(
        agent_init_success || agent_init["status"] == "blocked",
        "host bridge dispatch must return a canonical verdict: {agent_init}"
    );
    let request_path = agent_init["host_tool_bridge_request"]["request_path"]
        .as_str()
        .map(str::to_string)
        .or_else(|| {
            agent_init["artifact_refs"]["host_bridge_request_path"]
                .as_str()
                .map(str::to_string)
        })
        .or_else(|| {
            std::fs::read_dir(
                std::path::Path::new(&bridge_state_dir).join("host-tool-bridge/requests"),
            )
            .ok()?
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .find(|path| path.extension().and_then(|ext| ext.to_str()) == Some("json"))
            .map(|path| path.display().to_string())
        })
        .expect("host bridge parity must materialize a request path");
    let (direct_bridge, direct_bridge_success) = run_command_json_allow_failure(
        &[
            "agent",
            "host-bridge",
            "--request",
            &request_path,
            "--state-dir",
            &bridge_state_dir,
            "--json",
        ],
        &bridge_state_dir,
    );
    assert!(
        direct_bridge_success || direct_bridge["status"] == "blocked",
        "direct host bridge must fail closed with a canonical verdict: {direct_bridge}"
    );
    assert_zombie_d_host_bridge_shape(&direct_bridge);
    let (bridge_persisted, bridge_persisted_success) = run_command_json_allow_failure(
        &["taskflow", "run-graph", "status", bridge_run_id, "--json"],
        &bridge_state_dir,
    );
    assert!(
        bridge_persisted_success || bridge_persisted["status"] == "blocked",
        "persisted bridge status must be canonical: {bridge_persisted}"
    );
    assert_zombie_d_operator_shape(&bridge_persisted, "vida taskflow run-graph status");
    assert_eq!(
        direct_bridge["artifact_refs"]["request_path"],
        bridge_persisted["artifact_refs"]["host_bridge_request_path"],
        "direct host bridge and persisted run graph must identify the same request artifact"
    );
    let _ = fs::remove_dir_all(&bridge_state_dir);

    let (missing, success) = run_command_json_allow_failure(
        &[
            "taskflow",
            "route",
            "explain",
            "--dispatch-target",
            "designer",
            "--json",
        ],
        &state_dir,
    );
    assert!(!success);
    assert_eq!(missing["status"], "blocked");
    assert!(
        missing["blocker_codes"]
            .as_array()
            .is_some_and(|codes| codes.iter().any(|code| code == "route_missing"))
    );
    assert_zombie_d_operator_shape(&missing, "vida taskflow route explain");

    let _ = fs::remove_dir_all(project_root);
}

