#[test]
fn task_attempt_transition_fails_closed_on_invalid_task_or_stage_binding() {
    let state_dir = unique_state_dir();
    let task_id = unique_test_id("invalid-attempt-task");
    create_task_attempt_fixture(&state_dir, &task_id);
    let record = run_command_json(
        &[
            "task",
            "attempt",
            "record",
            &task_id,
            "--attempt-id",
            "attempt-invalid-binding",
            "--stage-id",
            "analysis",
            "--backend",
            "vibe",
            "--model-profile",
            "medium",
            "--isolation",
            "readonly",
            "--status",
            "submitted",
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(record["status"], "pass");

    let (stage_blocked, stage_success) = run_command_json_allow_failure(
        &[
            "task",
            "attempt",
            "transition",
            "attempt-invalid-binding",
            "--task-id",
            &task_id,
            "--stage-id",
            "design",
            "--status",
            "accepted",
            "--json",
        ],
        &state_dir,
    );
    assert!(!stage_success);
    assert_eq!(stage_blocked["status"], "blocked");
    assert_eq!(
        stage_blocked["blocker_codes"],
        serde_json::json!(["dispatch_packet_contract_invalid"])
    );

    let (status_blocked, status_success) = run_command_json_allow_failure(
        &[
            "task",
            "attempt",
            "transition",
            "attempt-invalid-binding",
            "--task-id",
            &task_id,
            "--stage-id",
            "analysis",
            "--status",
            "completed",
            "--json",
        ],
        &state_dir,
    );
    assert!(!status_success);
    assert_eq!(status_blocked["status"], "blocked");
    assert!(
        status_blocked["error"]
            .as_str()
            .expect("error should be string")
            .contains("expected one of submitted")
    );

    let help = run_command_capture(&["task", "attempt", "--help"], &state_dir);
    assert!(help.status.success());
    let help_stdout = String::from_utf8_lossy(&help.stdout);
    assert!(help_stdout.contains("compact TOON"));
    assert!(help_stdout.contains("--json"));
    assert!(help_stdout.contains("--status submitted"));
    assert!(help_stdout.contains("--status accepted"));
    assert!(
        !help_stdout.contains("--status completed"),
        "attempt help must not suggest non-canonical statuses: {help_stdout}"
    );
}

#[test]
fn task_attempt_dispatch_status_collect_and_stage_status_help_document_output_modes() {
    let state_dir = unique_state_dir();
    fs::create_dir_all(&state_dir).expect("create state dir");

    let attempt_help = run_and_assert_success(&["task", "attempt", "--help"], &state_dir);
    assert!(attempt_help.contains("dispatch"));
    assert!(attempt_help.contains("status"));
    assert!(attempt_help.contains("collect"));
    assert!(attempt_help.contains("consolidate"));
    assert!(attempt_help.contains("Default output is compact TOON"));
    assert!(attempt_help.contains("--json"));
    assert!(attempt_help.contains("attempt-artifacts/<attempt-id>.json"));

    for subcommand in ["dispatch", "status", "collect", "consolidate"] {
        let help = run_and_assert_success(&["task", "attempt", subcommand, "--help"], &state_dir);
        assert!(help.contains("--stage-id <STAGE>"));
        assert!(
            help.contains("--stage"),
            "{subcommand} should document the visible --stage alias"
        );
        assert!(help.contains("--json"));
        assert!(help.contains("--state-dir"));
        assert!(help.contains("compact TOON"));
    }
    for subcommand in ["collect", "record", "transition"] {
        let artifact_ref_help =
            run_and_assert_success(&["task", "attempt", subcommand, "--help"], &state_dir);
        for expected in [
            ".vida/data/state",
            "64 KiB",
            "65536 bytes",
            "stage-attempt-v1",
            "attempt_id",
            "task_id",
            "stage_id",
            "observed_facts",
            "facts array",
            "proof_commands",
        ] {
            assert!(
                artifact_ref_help.contains(expected),
                "{subcommand} help should document {expected}: {artifact_ref_help}"
            );
        }
    }
    let consolidate_help =
        run_and_assert_success(&["task", "attempt", "consolidate", "--help"], &state_dir);
    for expected in [
        "--consolidation-receipt",
        "--consolidator-profile",
        "--merge-policy",
        "--fact",
        "--hypothesis",
        "--conflict",
        "--partial-attempt-id",
        "--timeout-attempt-id",
        "--cap-limited-attempt-id",
    ] {
        assert!(
            consolidate_help.contains(expected),
            "consolidate help should document {expected}: {consolidate_help}"
        );
    }

    let stage_help = run_and_assert_success(&["task", "stage", "status", "--help"], &state_dir);
    assert!(stage_help.contains("--stage-id <STAGE>"));
    assert!(stage_help.contains("--stage"));
    assert!(stage_help.contains("--json"));
    assert!(stage_help.contains("--state-dir"));
    assert!(stage_help.contains("compact TOON"));
}

