#[test]
fn task_update_rejects_closed_task_proof_target_mutation() {
    let state_dir = unique_state_dir();
    fs::create_dir_all(&state_dir).expect("create state dir");
    let parent_id = unique_test_id("closed-proof-parent");
    let task_id = unique_test_id("closed-proof-task");
    let proof_target = "closed task proof target guard";
    let blocked_target = "cargo test -p vida blocked closed proof target mutation";
    create_epic_parent(&state_dir, &parent_id, "Closed proof parent", "open");
    let _ = run_command_json(
        &[
            "task",
            "create",
            &task_id,
            "Closed proof task",
            "--type",
            "task",
            "--parent-id",
            &parent_id,
            "--status",
            "in_progress",
            "--proof-target-literal",
            proof_target,
            "--json",
        ],
        &state_dir,
    );
    let receipt = run_command_json(
        &[
            "task",
            "proof",
            "attach-evidence",
            &task_id,
            "--proof-target",
            proof_target,
            "--result",
            "pass",
            "--artifact-ref",
            "artifacts/closed-proof-target-guard.json",
            "--evidence",
            "closed task proof target guard evidence",
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(receipt["status"], "pass");
    let closed = run_command_json(
        &[
            "task",
            "close",
            &task_id,
            "--reason",
            "Structured proof evidence recorded",
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(closed["status"], "pass");
    assert_eq!(closed["closed"], true);

    let (blocked, success) = run_command_json_allow_failure(
        &[
            "task",
            "update",
            &task_id,
            "--proof-target-literal",
            blocked_target,
            "--json",
        ],
        &state_dir,
    );
    assert!(!success, "closed task update should fail closed: {blocked}");
    assert_eq!(blocked["surface"], "vida task update");
    assert_eq!(blocked["status"], "blocked");
    assert_eq!(
        blocked["blocker_codes"],
        serde_json::json!(["task_update_closed_task_mutation_requires_reopen"])
    );
    assert_eq!(
        blocked["artifact_refs"]["reopen_surface"],
        serde_json::json!("vida task update")
    );

    let default_blocked = run_command_capture(
        &[
            "task",
            "update",
            &task_id,
            "--proof-target-literal",
            blocked_target,
        ],
        &state_dir,
    );
    assert!(
        !default_blocked.status.success(),
        "default closed task update should fail"
    );
    let default_stdout = String::from_utf8_lossy(&default_blocked.stdout);
    assert!(default_stdout.starts_with("vida task update\n"));
    assert!(default_stdout.contains("task_update_closed_task_mutation_requires_reopen"));
    assert!(!default_stdout.contains("--json"));

    let proof_status =
        run_command_json(&["task", "proof", "status", &task_id, "--json"], &state_dir);
    assert_eq!(proof_status["status"], "pass");
    assert_eq!(proof_status["satisfied_count"], 1);
    assert_eq!(proof_status["missing_count"], 0);
    assert_eq!(proof_status["proof_targets"][0]["target"], proof_target);

    let _ = fs::remove_dir_all(&state_dir);
}

#[test]
fn task_update_bulk_atomic_jsonl_contract() {
    let state_dir = unique_state_dir();
    fs::create_dir_all(&state_dir).expect("create state dir");
    let parent_id = unique_test_id("update-bulk-parent");
    let task_a = unique_test_id("update-bulk-a");
    let task_b = unique_test_id("update-bulk-b");
    create_epic_parent(&state_dir, &parent_id, "Update bulk parent", "open");
    create_task_fixture_row(
        &state_dir,
        &task_a,
        "Update bulk A",
        "task",
        "open",
        Some(&parent_id),
    );
    create_task_fixture_row(
        &state_dir,
        &task_b,
        "Update bulk B",
        "task",
        "open",
        Some(&parent_id),
    );

    let valid_path = format!("{state_dir}/updates-valid.jsonl");
    fs::write(
        &valid_path,
        format!(
            "{}\n{}\n",
            serde_json::json!({
                "task_id": task_a.clone(),
                "status": "in_progress",
                "priority": 1
            }),
            serde_json::json!({
                "task_id": task_b.clone(),
                "title": "Update bulk B changed",
                "add_labels": ["operator-projection"]
            })
        ),
    )
    .expect("write valid JSONL");

    let dry_run = run_command_json(
        &[
            "task",
            "update-bulk",
            "--file",
            &valid_path,
            "--dry-run",
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(dry_run["surface"], "vida task update-bulk");
    assert_eq!(dry_run["status"], "pass");
    assert_eq!(dry_run["atomic"], true);
    assert_eq!(dry_run["dry_run"], true);
    assert_eq!(dry_run["applied"], false);
    assert_eq!(dry_run["requested_count"], 2);
    assert_eq!(dry_run["updated_count"], 0);

    let invalid_path = format!("{state_dir}/updates-invalid.jsonl");
    let invalid_artifact = format!("{state_dir}/updates-invalid-result.json");
    fs::write(
        &invalid_path,
        format!(
            "{}\n{}\n",
            serde_json::json!({"task_id": task_a.clone(), "priority": 9}),
            serde_json::json!({"task_id": "missing-update-bulk-task", "title": "must not apply"})
        ),
    )
    .expect("write invalid JSONL");
    let (blocked, success) = run_command_json_allow_failure(
        &[
            "task",
            "update-bulk",
            "--file",
            &invalid_path,
            "--artifact-path",
            &invalid_artifact,
            "--json",
        ],
        &state_dir,
    );
    assert!(!success);
    assert_eq!(blocked["status"], "blocked");
    assert_eq!(blocked["applied"], false);
    assert_eq!(blocked["updated_count"], 0);
    assert!(
        blocked["blocker_codes"]
            .as_array()
            .expect("bulk blockers should be an array")
            .contains(&serde_json::json!("schema_contract_missing")),
        "blocked={blocked}"
    );
    assert!(std::path::Path::new(&invalid_artifact).is_file());
    let unchanged = run_command_json(&["task", "show", &task_a, "--json"], &state_dir);
    assert_eq!(unchanged["task"]["priority"], 1);

    let result_artifact = format!("{state_dir}/updates-result.json");
    let applied = run_command_json(
        &[
            "task",
            "update-bulk",
            "--file",
            &valid_path,
            "--artifact-path",
            &result_artifact,
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(applied["status"], "pass");
    assert_eq!(applied["applied"], true);
    assert_eq!(applied["updated_count"], 2);
    assert_eq!(applied["graph_validation"]["status"], "pass");
    assert_eq!(
        applied["mutation_summary"]
            .as_array()
            .expect("mutation summary should be an array")
            .len(),
        2
    );
    assert!(std::path::Path::new(&result_artifact).is_file());
    let updated_a = run_command_json(&["task", "show", &task_a, "--json"], &state_dir);
    let updated_b = run_command_json(&["task", "show", &task_b, "--json"], &state_dir);
    assert_eq!(updated_a["task"]["status"], "in_progress");
    assert_eq!(updated_a["task"]["priority"], 1);
    assert_eq!(updated_b["task"]["title"], "Update bulk B changed");
    assert!(
        updated_b["task"]["labels"]
            .as_array()
            .expect("updated labels should be an array")
            .contains(&serde_json::json!("operator-projection"))
    );

    let _ = fs::remove_dir_all(&state_dir);
}

