#[test]
fn agent_init_execute_dispatch_explicit_materialized_packet_reaches_host_bridge_gate() {
    let (project_root, state_dir) = project_bound_state_dir();
    append_internal_host_bridge_config(&project_root);

    let _ = run_and_assert_success(&["boot"], &state_dir);
    let parent_id = "agent-init-explicit-materialized-parent";
    let task_id = "agent-init-explicit-materialized-task";
    create_epic_parent(
        &state_dir,
        parent_id,
        "Agent init explicit materialized parent",
        "open",
    );
    let task = run_command_json(
        &[
            "task",
            "create",
            task_id,
            "Agent init explicit materialized task",
            "--type",
            "runtime_defect",
            "--status",
            "in_progress",
            "--priority",
            "1",
            "--parent-id",
            parent_id,
            "--owned-path",
            "crates/vida/src/init_surfaces.rs",
            "--json",
        ],
        &state_dir,
    );
    assert_eq!(task["status"], "pass");

    let dispatch = run_command_json(
        &[
            "agent",
            "dispatch-next",
            "--dev-team",
            "--current-task-id",
            task_id,
            "--lanes",
            "1",
            "--state-dir",
            &state_dir,
            "--json",
        ],
        &state_dir,
    );
    let packet_path = dispatch["packet_materialization"]["artifacts"][0]["dispatch_packet_path"]
        .as_str()
        .expect("materialized packet path should render");
    let output = run_with_state_lock_retry(|| {
        let mut command = vida();
        command
            .args([
                "agent-init",
                "--dispatch-packet",
                packet_path,
                "--execute-dispatch",
                "--state-dir",
                &state_dir,
                "--json",
            ])
            .env("VIDA_STATE_DIR", &state_dir)
            .env_remove("VIDA_AGENT_INIT_EXECUTE_DISPATCH_WORKER");
        command
    });
    let execute: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap_or_else(|error| {
        panic!(
            "json output should parse for explicit dispatch packet: {error}\nstatus: {:?}\nstdout: {}\nstderr: {}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        )
    });
    assert_eq!(execute["status"], "blocked");
    assert_eq!(
        execute["blocker_code"], "host_tool_bridge_adapter_required",
        "explicit packet should emit host bridge adapter request: {execute}"
    );
    assert_eq!(
        execute["blocker_codes"],
        serde_json::json!(["host_tool_bridge_adapter_required"]),
        "explicit packet should emit blocker_codes parity: {execute}"
    );
    assert_eq!(
        execute["shared_fields"]["blocker_codes"], execute["blocker_codes"],
        "shared_fields should mirror blocker_codes: {execute}"
    );
    assert_eq!(
        execute["operator_contracts"]["blocker_codes"], execute["blocker_codes"],
        "operator_contracts should mirror blocker_codes: {execute}"
    );
    assert_eq!(
        execute["dispatch_target"], "analyst",
        "fresh explicit packet must reach the dispatch/prelaunch layer: {execute}"
    );
    assert_eq!(
        execute["host_tool_bridge_request"]["packet_path"],
        packet_path
    );

    let _ = fs::remove_dir_all(&project_root);
}

